contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.sendMoney{value: amount}(address(this), 0, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        if (reverted) {
            assert(afterBalance == beforeBalance);
        } else {
            assert(beforeBalance - afterBalance == amount);
        }
    }

    receive() external payable {}
}

