pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _run(address target, uint256 value, bytes memory data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        vm.assume(msg.sender == c.owner());
        uint preBalance = address(c).balance;
        uint256 preDeposits;
        try c.depositsCount() returns (uint256 __r) { preDeposits = __r; } catch { return; }
        bool reverted = false;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((reverted && address(c).balance == preBalance && c.depositsCount() == preDeposits) ||
            (!reverted && address(c).balance == preBalance - value && c.depositsCount() == preDeposits));
    }

    function testFuzz_run(address target, uint256 value, bytes memory data) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, value, data);
    }

    receive() external payable {}
}

